/** 音（BGM はサイド画面が表示されている間だけ流れる） */
export const SOUND = {
  /** サイド画面が表示されているかを確かめる間隔（ミリ秒） */
  checkMs: 3_000,
}

/** セーブの書き出し / 読み込み */
export const SAVE_FILES = {
  /** 読み込むファイル（または貼り付けた JSON）の大きさの上限。これより大きいものは読まない */
  importMaxBytes: 1_000_000,
  /** 同じ名前のファイルがあったとき、-2, -3 … と番号を付けて試す最大の数 */
  maxNameTries: 100,
}

