  at: number
}

/** 画面の言語。auto は Claude Code の言語設定に合わせる（取れなければ日本語） */
export type Language = 'auto' | 'ja' | 'en'

export type Settings = {
  /** 強ければ装備・弱ければ売却を自動で決める */
